from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
DOCS=ROOT/'docs'

def shade(cell, fill):
    tcPr=cell._tc.get_or_add_tcPr(); shd=OxmlElement('w:shd'); shd.set(qn('w:fill'),fill); tcPr.append(shd)

def set_cell_text(cell,text,bold=False):
    cell.text=''; p=cell.paragraphs[0]; r=p.add_run(text); r.bold=bold; p.paragraph_format.space_after=Pt(0); cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER

def title(doc,text,subtitle=None):
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run(text); r.bold=True; r.font.size=Pt(18)
    if subtitle:
        p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run(subtitle); r.italic=True; r.font.size=Pt(11)

def h(doc,text,level=1): doc.add_heading(text,level=level)
def para(doc,text,bold_prefix=None):
    p=doc.add_paragraph()
    if bold_prefix and text.startswith(bold_prefix): p.add_run(bold_prefix).bold=True; p.add_run(text[len(bold_prefix):])
    else: p.add_run(text)
    p.paragraph_format.space_after=Pt(6)
    return p

def bullets(doc,items):
    for x in items: doc.add_paragraph(x,style='List Bullet')

def table(doc,headers,rows,widths=None):
    t=doc.add_table(rows=1,cols=len(headers)); t.style='Table Grid'; t.alignment=WD_TABLE_ALIGNMENT.CENTER
    for c,txt in zip(t.rows[0].cells,headers): set_cell_text(c,txt,True); shade(c,'D9EAF7')
    for row in rows:
        cells=t.add_row().cells
        for c,txt in zip(cells,row): set_cell_text(c,str(txt))
    return t

def setup(doc):
    sec=doc.sections[0]; sec.top_margin=Inches(.7); sec.bottom_margin=Inches(.7); sec.left_margin=Inches(.9); sec.right_margin=Inches(.7)
    styles=doc.styles; styles['Normal'].font.name='Times New Roman'; styles['Normal']._element.rPr.rFonts.set(qn('w:eastAsia'),'Times New Roman'); styles['Normal'].font.size=Pt(12)
    for s in ['Heading 1','Heading 2','Heading 3']:
        styles[s].font.name='Times New Roman'; styles[s]._element.rPr.rFonts.set(qn('w:eastAsia'),'Times New Roman')

